import type { IRProgram } from "../ir.js";

export function emitLiveEvaluations(program: IRProgram): string {
  const evaluations = program.evaluations.map((value) => ({
    name: value.name,
    agent: value.agentName,
    input: value.inputFunction,
    expected: value.expectedFunction,
  }));
  return [
    "// Generated by Evermore. Paid, opt-in, real-model evaluations.",
    'import { evermoreFunctions } from "./generated/functions.js";',
    'import { executeEvermoreAgent } from "./generated/runtime.js";',
    'import { createOpenAIProvider } from "./generated/openai-provider.js";',
    'const cases = ' + JSON.stringify(evaluations) + ' as const;',
    'const model = process.env.EVERMORE_MODEL;',
    'const inputPrice = Number(process.env.EVERMORE_INPUT_USD_PER_MILLION);',
    'const outputPrice = Number(process.env.EVERMORE_OUTPUT_USD_PER_MILLION);',
    'if (!model || !process.env.OPENAI_API_KEY || !process.env.EVERMORE_INPUT_USD_PER_MILLION ||',
    '  !process.env.EVERMORE_OUTPUT_USD_PER_MILLION ||',
    '  !Number.isFinite(inputPrice) || !Number.isFinite(outputPrice)) {',
    '  throw new Error("Set OPENAI_API_KEY, EVERMORE_MODEL and both current token prices");',
    '}',
    'const results: Array<{name:string; pass:boolean; latencyMs:number; tokens:number|null; costUsd:number|null; error?:string}> = [];',
    'for (const item of cases) {',
    '  const input = (evermoreFunctions[item.input as keyof typeof evermoreFunctions] as () => unknown)();',
    '  const expected = (evermoreFunctions[item.expected as keyof typeof evermoreFunctions] as () => unknown)();',
    '  let tokens: number | null = null;',
    '  let costUsd: number | null = null;',
    '  const provider = createOpenAIProvider({model, inputUsdPerMillion:inputPrice,',
    '    outputUsdPerMillion:outputPrice, onUsage(value) { tokens=value.tokens; costUsd=value.costUsd; }});',
    '  const start = performance.now();',
    '  try {',
    '    const actual = await executeEvermoreAgent(item.agent, input, { provider,',
    '      approve: () => false, context: () => null });',
    '    results.push({name:item.name, pass:JSON.stringify(actual)===JSON.stringify(expected),',
    '      latencyMs:performance.now()-start, tokens, costUsd});',
    '  } catch (error) {',
    '    results.push({name:item.name, pass:false, latencyMs:performance.now()-start, tokens, costUsd,',
    '      error:error instanceof Error ? error.message : String(error)});',
    '  }',
    '}',
    'const latency = results.map((r)=>r.latencyMs).sort((a,b)=>a-b);',
    'console.log(JSON.stringify({model, numberOfCases:results.length,',
    '  exactMatchRate:results.length ? results.filter((r)=>r.pass).length/results.length : null,',
    '  p95LatencyMs:latency.length ? latency[Math.ceil(.95*latency.length)-1] : null, results},null,2));',
    'if (results.some((r)=>!r.pass)) process.exitCode = 1;',
    '',
  ].join("\n");
}
